public static String deduplicate(String code, Predicate<String> inUse) {
    if (!inUse.test(code)) {
        return code;
    }
    for (int n = 2; ; n++) {
        String candidate = code + "-" + n;
        if (!inUse.test(candidate)) {
            return candidate;
        }
    }
}

